using System;
using System.Collections.Concurrent;
using System.Net.WebSockets;
using System.Threading;
using System.Threading.Tasks;
using Grpc.Core;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.DependencyInjection;

namespace GrpcStreamingService
{
    public class ConnectionPoolEntry
    {
        public WebSocket Socket { get; set; }
        public string AuthenticatedUserId { get; set; }
        public string SessionToken { get; set; }
        public DateTime LastActivity { get; set; }
        public bool IsReusable { get; set; }
        public int ChannelId { get; set; }
    }

    public class WebSocketConnectionPool
    {
        private readonly ConcurrentDictionary<int, ConnectionPoolEntry> _pool = new();
        private readonly SemaphoreSlim _poolLock = new(1, 1);
        private int _nextChannelId = 0;

        public async Task<ConnectionPoolEntry> AcquireConnectionAsync(HttpContext context)
        {
            var userId = context.User?.Identity?.Name;
            var sessionToken = context.Request.Headers["X-Session-Token"].ToString();

            if (string.IsNullOrEmpty(userId) || string.IsNullOrEmpty(sessionToken))
                return null;

            // Try to find a reusable connection for this specific session
            foreach (var kvp in _pool)
            {
                var entry = kvp.Value;
                if (entry.IsReusable && entry.Socket.State == WebSocketState.Open
                    && entry.SessionToken == sessionToken
                    && entry.AuthenticatedUserId == userId)
                {
                    // Mark as in-use - only reuse if session matches
                    entry.IsReusable = false;
                    entry.LastActivity = DateTime.UtcNow;
                    return entry;
                }
            }

            // No reusable connection found, create new
            var ws = await context.WebSockets.AcceptWebSocketAsync("grpc-websocket-channel");
            var channelId = Interlocked.Increment(ref _nextChannelId);
            var newEntry = new ConnectionPoolEntry
            {
                Socket = ws,
                AuthenticatedUserId = userId,
                SessionToken = sessionToken,
                LastActivity = DateTime.UtcNow,
                IsReusable = false,
                ChannelId = channelId
            };
            _pool.TryAdd(channelId, newEntry);
            return newEntry;
        }

        public void ReleaseConnection(ConnectionPoolEntry entry)
        {
            entry.IsReusable = true;
            entry.LastActivity = DateTime.UtcNow;
            // Connection remains in pool for reuse - session binding preserved
        }

        public ConnectionPoolEntry GetByChannelId(int channelId)
        {
            _pool.TryGetValue(channelId, out var entry);
            return entry;
        }
    }

    public class GrpcStreamHandler
    {
        private readonly WebSocketConnectionPool _pool;

        public GrpcStreamHandler(WebSocketConnectionPool pool)
        {
            _pool = pool;
        }

        public async Task HandleBidiStream(HttpContext context)
        {
            if (!context.WebSockets.IsWebSocketRequest)
            {
                context.Response.StatusCode = 400;
                return;
            }

            var connection = await _pool.AcquireConnectionAsync(context);
            if (connection == null)
            {
                context.Response.StatusCode = 401;
                return;
            }
            try
            {
                await ProcessGrpcFrames(connection, context);
            }
            finally
            {
                _pool.ReleaseConnection(connection);
            }
        }

        private async Task ProcessGrpcFrames(ConnectionPoolEntry connection, HttpContext context)
        {
            var buffer = new byte[4096];
            while (connection.Socket.State == WebSocketState.Open)
            {
                var result = await connection.Socket.ReceiveAsync(
                    new ArraySegment<byte>(buffer), CancellationToken.None);

                if (result.MessageType == WebSocketMessageType.Close)
                    break;

                // Validate the frame belongs to the authenticated session
                var frameSessionToken = ExtractSessionFromFrame(buffer, result.Count);
                if (ValidateFrameOwnership(connection, frameSessionToken))
                {
                    await DispatchToGrpcService(connection, buffer, result.Count);
                }
            }
        }

        private bool ValidateFrameOwnership(ConnectionPoolEntry connection, string frameToken)
        {
            // Verify the frame's session matches the connection's bound session
            if (string.IsNullOrEmpty(frameToken))
                return false; // Reject frames without explicit session

            return connection.SessionToken == frameToken;
        }

        private string ExtractSessionFromFrame(byte[] buffer, int length)
        {
            // gRPC frame header: 1 byte compressed flag, 4 bytes length, then payload
            if (length < 5) return null;
            // Custom metadata: first 32 bytes after gRPC header contain session token
            if (length < 37) return null;
            return System.Text.Encoding.UTF8.GetString(buffer, 5, 32).TrimEnd('\0');
        }

        private async Task DispatchToGrpcService(ConnectionPoolEntry connection, byte[] data, int length)
        {
            // Forward to gRPC service implementation
            var response = ProcessGrpcCall(data, length, connection.AuthenticatedUserId);
            await connection.Socket.SendAsync(
                new ArraySegment<byte>(response),
                WebSocketMessageType.Binary, true, CancellationToken.None);
        }

        private byte[] ProcessGrpcCall(byte[] data, int length, string userId)
        {
            // Simulated gRPC response with user context
            var responsePayload = $"Response for user: {userId}";
            return System.Text.Encoding.UTF8.GetBytes(responsePayload);
        }
    }

    public class Startup
    {
        public void ConfigureServices(IServiceCollection services)
        {
            services.AddSingleton<WebSocketConnectionPool>();
            services.AddSingleton<GrpcStreamHandler>();
            services.AddAuthentication();
            services.AddAuthorization();
        }

        public void Configure(IApplicationBuilder app)
        {
            app.UseWebSockets();
            app.UseAuthentication();
            app.UseAuthorization();
            app.Use(async (context, next) =>
            {
                if (context.Request.Path == "/grpc-stream")
                {
                    var handler = context.RequestServices.GetRequiredService<GrpcStreamHandler>();
                    await handler.HandleBidiStream(context);
                }
                else
                {
                    await next();
                }
            });
        }
    }
}
